// ============================================================
// Keystone PT Script  -  Generated by Keystone Automation
//
// HOW TO USE
//   1. Open Packet Tracer
//   2. Place ONE seed device on the canvas for each type below:
//        - One 2911  (router)
//   3. Extensions  ->  Scripting  ->  Edit File Script Module
//   4. Load this file and click  Run
//   5. Manually cable the connections shown in the console output
//   6. Delete the original seed device(s) from the canvas
//   7. File  ->  Save As  ->  your_lab.pkt
//
// Topology: 2 device(s), 0 connection(s)
// ============================================================

function main()
{
    dprint("=== KEYSTONE TOPOLOGY BUILDER ===");
    dprint("");

    try {

        var network    = ipc.network();
        var activeFile = ipc.appWindow().getActiveFile();

        dprint("Seed devices on canvas: " + network.getDeviceCount());

        // ===== PHASE 1: LOCATE SEED DEVICES =====
        dprint("[1/4] Locating seed devices...");
        var seeds = {};
        for (var i = 0; i < network.getDeviceCount(); i++) {
            var d     = network.getDeviceAt(i);
            var model = d.getModel();
            if (!seeds[model]) {
                seeds[model] = d;
                dprint("  OK  Found seed: " + model + " (" + d.getName() + ")");
            }
        }

        if (!seeds["2911"]) {
            dprint("  ERR  Missing seed: 2911");
            dprint("       Add one router (2911) to the canvas and re-run.");
            return;
        }

        // ===== PHASE 2: CREATE DEVICES =====
        dprint("[2/4] Creating devices...");
        var devs = {};

        // --- R1 ---
        activeFile.duplicateDevice(seeds["2911"]);
        var dev_R1 = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_R1.moveToLocationCentered(120, 120);
        devs["R1"] = dev_R1;
        dprint("  +  R1 at (120, 120)");
        java.lang.Thread.sleep(300);

        // --- R2 ---
        activeFile.duplicateDevice(seeds["2911"]);
        var dev_R2 = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_R2.moveToLocationCentered(340, 120);
        devs["R2"] = dev_R2;
        dprint("  +  R2 at (340, 120)");
        java.lang.Thread.sleep(300);

        // ===== PHASE 3: CONNECTIONS (manual cabling required) =====
        dprint("[3/4] Connections to cable manually:");
        dprint("  (no connections defined in topology)");

        // ===== PHASE 4: CONFIGURE DEVICES =====
        dprint("[4/4] Configuring devices (this may take a moment)...");

        dprint("  >> R1");
        configureDevice(devs["R1"], ["enable", "configure terminal", "hostname R1", "interface GigabitEthernet0/0/0", " description Link to R2", " ip address 10.0.1.1 255.255.255.0", " no shutdown", " exit", "router ospf 1", " router-id 1.1.1.1", " network 10.0.1.0 0.0.0.255 area 0", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> R2");
        configureDevice(devs["R2"], ["enable", "configure terminal", "hostname R2", "interface GigabitEthernet0/0/0", " description Link to R1", " ip address 10.0.1.2 255.255.255.0", " no shutdown", " exit", "router ospf 1", " router-id 2.2.2.2", " network 10.0.1.0 0.0.0.255 area 0", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("");
        dprint("=== TOPOLOGY COMPLETE ===");
        dprint("  Devices created : 2");
        dprint("  Connections     : 0 (see above for cabling)");
        dprint("");
        dprint("Next steps:");
        dprint("  1. Cable the connections listed above");
        dprint("  2. Delete the original seed device(s)");
        dprint("  3. File -> Save As -> your_lab.pkt");

    } catch(e) {
        dprint("FATAL ERROR: " + e.message);
        dprint(e.stack);
    }
}


// ============================================================
// Helper: send a list of IOS CLI commands to a device
// ============================================================
function configureDevice(device, commands)
{
    try {
        var cli = device.getCommandLine();
        if (cli == null) {
            dprint("  WARN  No CLI available for " + device.getName());
            return;
        }

        // Dismiss the initial configuration dialog if it appears
        var initialOut = cli.getOutput();
        if (initialOut.indexOf("initial configuration dialog") > -1) {
            cli.enterCommand("no");
            java.lang.Thread.sleep(500);
        }

        // Send each command with a short delay
        for (var i = 0; i < commands.length; i++) {
            cli.enterCommand(commands[i]);
            java.lang.Thread.sleep(100);
        }

        dprint("  OK  " + device.getName());

    } catch(e) {
        dprint("  ERR  " + device.getName() + ": " + e.message);
    }
}


function cleanUp()
{
    dprint("Script cleanup complete.");
}
